```go
package main

import (
    "errors"
    "fmt"
)

type ValidationError struct {
    Field  string
    Reason string
}

func (e *ValidationError) Error() string {
    return e.Field + ": " + e.Reason
}

func validateAge(age int) error {
    if age <= 0 {
        return &ValidationError{Field: "age", Reason: "must be positive"}
    }
    return nil
}

func main() {
    err := validateAge(0)
    var validation *ValidationError
    if errors.As(err, &validation) {
        fmt.Println(validation.Field, validation.Reason)
    }
}
```
The output is `age must be positive`; the caller obtains fields without parsing the formatted error sentence.

```go
package main

import (
    "errors"
    "fmt"
)

type LineError struct{ Line int }

func (e *LineError) Error() string {
    return fmt.Sprintf("invalid input on line %d", e.Line)
}

func parse() error {
    return fmt.Errorf("parse upload: %w", &LineError{Line: 7})
}

func main() {
    err := parse()
    var line *LineError
    fmt.Println(errors.As(err, &line), line.Line)
}
```
The program prints `true 7`, although the `LineError` is not the outermost error value.

```go
package main

import (
    "errors"
    "fmt"
)

var ErrNotFound = errors.New("not found")

type ValidationError struct{ Field string }

func (e *ValidationError) Error() string { return e.Field + " is invalid" }

func main() {
    missing := fmt.Errorf("user 42: %w", ErrNotFound)
    invalid := error(&ValidationError{Field: "email"})
    var validation *ValidationError

    fmt.Println(errors.Is(missing, ErrNotFound))
    fmt.Println(errors.As(invalid, &validation), validation.Field)
}
```
The sentinel answers a category question; the custom type provides the `email` field for a richer response.
